package com.financetrack.controller;
import com.financetrack.repository.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") public class DashboardController {
 private final IncomeRepository incomes;private final ExpenseRepository expenses;private final UserRepository users;public DashboardController(IncomeRepository i,ExpenseRepository e,UserRepository u){incomes=i;expenses=e;users=u;}
 private Long uid(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication auth){Long id=uid(auth);LocalDate now=LocalDate.now(),start=now.withDayOfMonth(1),end=now.withDayOfMonth(now.lengthOfMonth());var inc=incomes.findByUserIdAndOccurredOnBetweenOrderByOccurredOnDesc(id,start,end).stream().map(x->x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);var exp=expenses.total(id,start,end);var cats=expenses.byCategory(id,start,end).stream().map(x->Map.of("name",x[0],"value",x[1])).toList();return Map.of("income",inc,"expenses",exp,"balance",inc.subtract(exp),"savings",inc.subtract(exp),"savingsRate",inc.signum()==0?BigDecimal.ZERO:inc.subtract(exp).multiply(BigDecimal.valueOf(100)).divide(inc,2,RoundingMode.HALF_UP),"distribution",cats,"month",start.toString());}
 @GetMapping("/predictions") public Map<String,Object> predictions(Authentication auth){Long id=uid(auth);LocalDate month=YearMonth.now().atDay(1);List<BigDecimal> vals=new ArrayList<>();for(int i=5;i>=0;i--){LocalDate m=month.minusMonths(i);vals.add(expenses.total(id,m,m.withDayOfMonth(m.lengthOfMonth())));}BigDecimal avg=vals.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(vals.size()),2,RoundingMode.HALF_UP);return Map.of("history",vals,"average",avg,"forecast",avg,"targetMonth",month.plusMonths(1).toString(),"message","La estimación usa el promedio de los últimos seis meses completos.");}
}
